function c(t){const r=Math.max(0,Math.ceil(t/1e3)),n=Math.floor(r/60),s=r%60;return`${String(n).padStart(2,"0")}:${String(s).padStart(2,"0")}`}function f(t){const r=Math.floor(t/60),n=t%60;return r<=0?`${n}s`:`${r}:${String(n).padStart(2,"0")}`}function m(t,r=new Date){if(!t.quietHoursEnabled)return!1;const[n,s]=t.quietHoursStart.split(":").map(Number),[u,i]=t.quietHoursEnd.split(":").map(Number),e=r.getHours()*60+r.getMinutes(),a=n*60+s,o=u*60+i;return a===o?!1:a<o?e>=a&&e<o:e>=a||e<o}function d(t,r){const n=t+r;return n===0?0:Math.round(t/n*100)}export{d as a,c as b,f,m as i};
